    stack = []
    opening_chars = '([{'
    closing_chars = ')]}'
    for char in s:
        if char in opening_chars:
            stack.append(char)
        elif char in closing_chars:
            if not stack or stack.pop() != opening_chars[closing_chars.index(char)]:
                return False
    return not stack

